            if (queryCommand.ResolvedCommandTimeout is int commandTimeout)
                dbCommand.CommandTimeout = commandTimeout;

            if (!noParams)
            {
                var parameterList = @params!;
                for (var i = 0; i < parameterList.Count; i++)
                {
